import { test } from "node:test";
import assert from "node:assert/strict";
import { setTimeout as sleep } from "node:timers/promises";
import { RestaurantPageService, type RestaurantPage } from "../src/storefront/restaurantPage.ts";
import type { Menu } from "../src/storefront/deps.ts";

const menu: Menu = {
    restaurantId: "r1",
    restaurantName: "Pho Corner",
    items: [
        { id: "pho", name: "Beef pho", priceCents: 1450, available: true },
        { id: "roll", name: "Spring rolls", priceCents: 700, available: true },
        { id: "bao", name: "Pork bao", priceCents: 900, available: false },
    ],
};

function setup() {
    let now = 1_000_000;
    const calls = { menu: 0, eta: 0, promos: 0, reviews: 0 };
    const state = { menuDown: false, etaDelayMs: 0, reviewsDown: false };
    const deps = {
        menus: { getMenu: async (id: string) => (calls.menu++, state.menuDown ? Promise.reject(new Error("menu db down")) : id === "r1" ? menu : null) },
        eta: {
            async estimateMinutes() {
                calls.eta++;
                if (state.etaDelayMs) await sleep(state.etaDelayMs);
                return 25;
            },
        },
        promos: { active: async () => (calls.promos++, [{ itemId: "roll", percentOff: 20 }]) },
        reviews: {
            async summary() {
                calls.reviews++;
                if (state.reviewsDown) throw new Error("reviews: 502 Bad Gateway");
                return { average: 4.6, count: 312 };
            },
        },
    };
    const pages = new RestaurantPageService(deps, () => now, 30);
    return { pages, calls, state, advance: (ms: number) => void (now += ms) };
}

test("a healthy page lists available items with promo prices and is cached", async () => {
    const { pages, calls } = setup();
    const first = await pages.render("r1", "zone-9");
    const page = first.body as RestaurantPage;
    assert.deepEqual(page.items.map((i) => [i.id, i.salePriceCents]), [["pho", null], ["roll", 560]]);
    assert.deepEqual([page.etaMinutes, page.reviews.count, page.degraded], [25, 312, []]);
    assert.equal(first.headers["Cache-Control"], "public, max-age=60");
    const second = await pages.render("r1", "zone-9");
    assert.equal(second.headers["X-Cache"], "hit");
    assert.deepEqual(calls, { menu: 1, eta: 1, promos: 1, reviews: 1 });
});

test("a failing reviews service only blanks the reviews section", async () => {
    const { pages, state } = setup();
    state.reviewsDown = true;
    const res = await pages.render("r1", "zone-9");
    const page = res.body as RestaurantPage;
    assert.equal(res.status, 200);
    assert.deepEqual(page.reviews, { average: null, count: 0 });
    assert.deepEqual(page.degraded, ["reviews"]);
    assert.equal(page.items.length, 2);
    assert.equal(res.headers["Cache-Control"], "no-store");
});

test("a slow ETA service is cut off and the page renders without an ETA", async () => {
    const { pages, state } = setup();
    state.etaDelayMs = 200;
    const res = await pages.render("r1", "zone-9");
    const page = res.body as RestaurantPage;
    assert.equal(page.etaMinutes, null);
    assert.deepEqual(page.degraded, ["eta"]);
});

test("the menu is required: down means 503, unknown means 404", async () => {
    const { pages, state } = setup();
    assert.equal((await pages.render("nope", "zone-9")).status, 404);
    state.menuDown = true;
    const res = await pages.render("r1", "zone-9");
    assert.equal(res.status, 503);
    assert.equal(res.headers["Retry-After"], "5");
});

test("reviews come back as soon as the reviews service recovers", async () => {
    const { pages, state, advance } = setup();
    state.reviewsDown = true;
    await pages.render("r1", "zone-9");
    state.reviewsDown = false;
    advance(2_000);
    const res = await pages.render("r1", "zone-9");
    console.log("after recovery:", res.headers, (res.body as RestaurantPage).reviews);
    assert.deepEqual((res.body as RestaurantPage).reviews, { average: 4.6, count: 312 });
});

test("a degraded page is never served from cache", async () => {
    const { pages, state, calls } = setup();
    state.etaDelayMs = 200;
    await pages.render("r1", "zone-9");
    state.etaDelayMs = 0;
    const res = await pages.render("r1", "zone-9");
    assert.equal(res.headers["X-Cache"], "miss");
    assert.equal(calls.eta, 2);
    assert.equal((res.body as RestaurantPage).etaMinutes, 25);
});

test("pages are cached per delivery zone and expire after a minute", async () => {
    const { pages, calls, advance } = setup();
    await pages.render("r1", "zone-9");
    await pages.render("r1", "zone-2");
    assert.equal(calls.eta, 2);
    advance(60_000);
    assert.equal((await pages.render("r1", "zone-9")).headers["X-Cache"], "miss");
    assert.equal(calls.menu, 3);
});
